Boolean dei_prk_offset( void )
{    
    CRITICAL;
         
    TskTimeout offset ; 
    
    
    C_ENTER ; 
    {
        if( dei_prk_offset_length < 1000 ) 
        {
            offset = 1000 - dei_prk_offset_length ; 
        }
        else
        {
            offset = 0 ; 
        }; 
    }
    C_LEAVE ;  


    if( os_pip_test_empty(dei_prk_pip) == FALSE ) return TRUE ;
            
    if( offset )
    {
        if( os_irq_wait( dei_prk_irq , TRUE , offset ) ) return TRUE ; 
    }
    else
    {
        os_irq_clr( dei_prk_irq )  ;
    };        
    
    return FALSE ; 
}

